package com.samosaking.nawalgarh;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.net.Uri;import android.os.*;import android.webkit.*;import androidx.core.app.*;import com.google.firebase.FirebaseException;import com.google.firebase.auth.*;import com.google.firebase.firestore.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity{
static final int LOC=4101;static final double LAT=27.8514056,LON=75.2711528,R=5;static final String CH="order_status";WebView w;FirebaseAuth a;FirebaseFirestore db;ListenerRegistration sl;String pn,pp,pa,pi;int ps;boolean busy;String vid,last="";
@Override public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel(CH,"Order status",NotificationManager.IMPORTANCE_DEFAULT));w=new WebView(this);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setAllowFileAccessFromFileURLs(true);s.setAllowUniversalAccessFromFileURLs(true);w.setWebViewClient(new WebViewClient(){public void onPageFinished(WebView v,String u){images();premium();v.postDelayed(()->{images();premium();},600);loadLast();}public boolean shouldOverrideUrlLoading(WebView v,String u){try{if(u.startsWith("tel:")||u.startsWith("https://wa.me/")||u.startsWith("whatsapp:")){startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));return true;}}catch(Exception e){}return false;}});w.addJavascriptInterface(new Bridge(),"AndroidBridge");setContentView(w);a=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();if(a.getCurrentUser()==null)a.signInAnonymously().addOnSuccessListener(x->js("window.authReady&&window.authReady();"));w.loadUrl("file:///android_asset/index.html");}
void js(String x){runOnUiThread(()->{if(w!=null)w.evaluateJavascript(x,null);});}
void images(){js("(function(){var m={'Samosa':'samosa.jpg','Kachori':'samosa.jpg','Mirchi Bada':'mirchi-bada.jpg','Dahi Bhalla Plate 1':'dahi-bhalla-1.jpg','Dahi Bhalla Plate 2':'dahi-bhalla-2.jpg','Pizza':'pizza.jpg','Wraps':'wraps.jpg','Momos':'momos.jpg','Burger':'burger.jpg','Pasta':'pasta.jpg','Manchurian':'manchurian.jpg','Kaju Katli':'kaju-katli.jpg','Rasgulla':'rasgulla.jpg','Rajbhog':'rasgulla.jpg','Gulab Jamun':'gulab-jamun.jpg','Sohan Papdi':'sohan-papdi.jpg','Milk Cake':'milk-cake.jpg','Kalakand':'kalakand.jpg','Dilkushal':'dilkushal.jpg','Peda':'milk-cake.jpg','Petha':'kalakand.jpg','Namkin':'sohan-papdi.jpg','Rasmalai':'dahi-bhalla-1.jpg','Dahi (Curd)':'dahi-bhalla-2.jpg'};document.querySelectorAll('.card').forEach(c=>{var h=c.querySelector('h3'),v=c.querySelector('.visual');if(!h||!v||!m[h.textContent.trim()])return;var i=v.querySelector('img');if(!i){i=document.createElement('img');i.style.cssText='width:100%;height:100%;object-fit:cover;border-radius:13px';v.innerHTML='';v.appendChild(i)}i.src='product-images/'+m[h.textContent.trim()]})})();");}
void premium(){js("(function(){if(window.__skp)return;window.__skp=1;var x=document.createElement('script');x.src='premium.js';x.onload=function(){window.SKPremium&&SKPremium.init()};document.head.appendChild(x)})();");}
void send(String p){PhoneAuthOptions o=PhoneAuthOptions.newBuilder(a).setPhoneNumber(p).setTimeout(60L,java.util.concurrent.TimeUnit.SECONDS).setActivity(this).setCallbacks(new PhoneAuthProvider.OnVerificationStateChangedCallbacks(){public void onVerificationCompleted(PhoneAuthCredential c){a.signInWithCredential(c).addOnSuccessListener(x->js("window.otpVerified("+JSONObject.quote(p)+");"));}public void onVerificationFailed(FirebaseException e){js("window.otpError("+JSONObject.quote(e.getMessage())+");");}public void onCodeSent(String id,PhoneAuthProvider.ForceResendingToken t){vid=id;js("window.otpSent();");}}).build();PhoneAuthProvider.verifyPhoneNumber(o);}
void verify(String c){if(vid==null){js("window.otpError('Please request OTP first.');");return;}a.signInWithCredential(PhoneAuthProvider.getCredential(vid,c)).addOnSuccessListener(x->js("window.otpVerified('verified');")).addOnFailureListener(e->js("window.otpError("+JSONObject.quote(e.getMessage())+");"));}
void order(String n,String p,String ad,String items,int sub){if(busy)return;pn=n;pp=p;pa=ad;pi=items;ps=sub;if(sub<100){js("window.orderError('Minimum order is ₹100.');");return;}if(a.getCurrentUser()==null){a.signInAnonymously().addOnSuccessListener(x->locate());}else locate();}
void locate(){if(Build.VERSION.SDK_INT>=23&&ActivityCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&ActivityCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOC);js("window.locationRequired&&window.locationRequired();");return;}LocationManager m=(LocationManager)getSystemService(LOCATION_SERVICE);Location l=null;try{l=m.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(l==null)l=m.getLastKnownLocation(LocationManager.NETWORK_PROVIDER);}catch(Exception e){}if(l!=null){distance(l);return;}try{m.requestSingleUpdate(LocationManager.NETWORK_PROVIDER,new LocationListener(){public void onLocationChanged(Location x){distance(x);}},null);}catch(Exception e){js("window.orderError('Location could not be read. Please enable GPS.');");}}
void distance(Location l){float[] d={0};Location.distanceBetween(l.getLatitude(),l.getLongitude(),LAT,LON,d);double km=d[0]/1000;js("window.locationResult&&window.locationResult("+JSONObject.quote(String.format(Locale.US,"%.2f",km))+");");if(km>R){pn=null;js("window.orderError('Delivery is available only within 5 km of Nansa Gate, Nawalgarh.');");return;}create();}
void create(){if(busy||a.getCurrentUser()==null)return;busy=true;try{Map<String,Object>o=new HashMap<>();o.put("userId",a.getCurrentUser().getUid());o.put("customerName",pn);o.put("mobile",pp);o.put("address",pa);o.put("paymentMethod","COD");o.put("subtotal",ps);o.put("deliveryFee",30);o.put("discount",0);o.put("total",ps+30);o.put("status","PLACED");o.put("createdAt",FieldValue.serverTimestamp());JSONArray ar=new JSONArray(pi);Map<String,Object>im=new HashMap<>();for(int i=0;i<ar.length();i++){JSONObject z=ar.getJSONObject(i);im.put(z.getString("id"),z.getInt("qty"));}o.put("items",im);db.collection("orders").add(o).addOnSuccessListener(r->{getPreferences(0).edit().putString("lastOrderId",r.getId()).putString("lastOrderItems",pi).apply();listen(r.getId());busy=false;pn=null;js("window.orderCreated("+JSONObject.quote(r.getId())+");");}).addOnFailureListener(e->{busy=false;js("window.orderError("+JSONObject.quote("Order save failed: "+e.getMessage())+");");});}catch(Exception e){busy=false;}}
void listen(String id){if(sl!=null)sl.remove();sl=db.collection("orders").document(id).addSnapshotListener((s,e)->{if(e!=null||s==null||!s.exists())return;String st=s.getString("status");if(st==null)st="PLACED";js("window.statusUpdate("+JSONObject.quote(st)+");");if(!st.equals(last)){last=st;if(!st.equals("PLACED")&&(Build.VERSION.SDK_INT<33||ActivityCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED))((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()%100000),new NotificationCompat.Builder(this,CH).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Samosa King – Order Update").setContentText("Order status: "+st).setAutoCancel(true).build());}});}
void loadLast(){String id=getPreferences(0).getString("lastOrderId",null);if(id!=null)listen(id);}
void history(){if(a.getCurrentUser()==null){js("window.renderHistory('[]')");return;}db.collection("orders").whereEqualTo("userId",a.getCurrentUser().getUid()).get().addOnSuccessListener(s->{try{List<DocumentSnapshot>l=new ArrayList<>(s.getDocuments());l.sort((x,y)->{Date dx=x.getDate("createdAt"),dy=y.getDate("createdAt");return dy==null?-1:dx==null?1:dy.compareTo(dx);});JSONArray out=new JSONArray();for(DocumentSnapshot d:l.subList(0,Math.min(30,l.size()))){JSONObject o=new JSONObject();o.put("id",d.getId());o.put("total",d.getLong("total")!=null?d.getLong("total"):0);o.put("status",String.valueOf(d.get("status")));o.put("date",d.getDate("createdAt")!=null?d.getDate("createdAt").toString():"Recent");Map<String,Object>im=d.get("items",Map.class);JSONArray ia=new JSONArray();if(im!=null)for(Map.Entry<String,Object>q:im.entrySet()){JSONObject z=new JSONObject();z.put("id",q.getKey());z.put("qty",((Number)q.getValue()).intValue());ia.put(z);}o.put("itemsJson",ia.toString());out.put(o);}js("window.renderHistory("+JSONObject.quote(out.toString())+");");}catch(Exception e){js("window.renderHistory('[]')");}}).addOnFailureListener(e->js("window.renderHistory('[]')"));}
void profile(){if(a.getCurrentUser()==null)return;db.collection("users").document(a.getCurrentUser().getUid()).get().addOnSuccessListener(d->{try{JSONObject o=new JSONObject();o.put("name",d.getString("name"));o.put("mobile",d.getString("mobile"));js("window.profileResult("+JSONObject.quote(o.toString())+");");}catch(Exception e){}});}
void saveProfile(String n,String p){if(a.getCurrentUser()==null)return;Map<String,Object>m=new HashMap<>();m.put("uid",a.getCurrentUser().getUid());m.put("name",n);m.put("mobile",p);m.put("updatedAt",FieldValue.serverTimestamp());db.collection("users").document(a.getCurrentUser().getUid()).set(m,SetOptions.merge()).addOnSuccessListener(x->js("window.profileSaved&&window.profileSaved();"));}
void addresses(){if(a.getCurrentUser()==null)return;db.collection("users").document(a.getCurrentUser().getUid()).collection("addresses").get().addOnSuccessListener(s->{try{JSONArray q=new JSONArray();for(DocumentSnapshot d:s){JSONObject o=new JSONObject();o.put("id",d.getId());o.put("label",String.valueOf(d.get("label")));o.put("address",String.valueOf(d.get("address")));q.put(o);}js("window.addressesResult("+JSONObject.quote(q.toString())+");");}catch(Exception e){}});}
void saveAddress(String l,String ad){if(a.getCurrentUser()==null||ad.trim().isEmpty())return;Map<String,Object>m=new HashMap<>();m.put("label",l);m.put("address",ad);m.put("createdAt",FieldValue.serverTimestamp());db.collection("users").document(a.getCurrentUser().getUid()).collection("addresses").add(m).addOnSuccessListener(x->addresses());}
void review(String id,int r,String c){if(a.getCurrentUser()==null||r<1||r>5)return;db.collection("orders").document(id).get().addOnSuccessListener(o->{if(!o.exists()||!a.getCurrentUser().getUid().equals(o.getString("userId"))||!"DELIVERED".equals(o.getString("status"))){js("window.reviewError('Only your delivered orders can be reviewed.');");return;}Map<String,Object>m=new HashMap<>();m.put("userId",a.getCurrentUser().getUid());m.put("orderId",id);m.put("rating",r);m.put("comment",c==null?"":c);m.put("createdAt",FieldValue.serverTimestamp());db.collection("reviews").document(id).set(m).addOnSuccessListener(x->js("window.reviewSaved&&window.reviewSaved();"));});}
void adminCheck(){if(a.getCurrentUser()==null){js("window.adminResult(false)");return;}db.collection("admins").document(a.getCurrentUser().getUid()).get().addOnSuccessListener(d->js("window.adminResult("+(d.exists()?"true":"false")+")"));}
void adminOrders(){if(a.getCurrentUser()==null)return;db.collection("admins").document(a.getCurrentUser().getUid()).get().addOnSuccessListener(d->{if(!d.exists()){js("window.adminError('Admin access denied.');");return;}db.collection("orders").get().addOnSuccessListener(s->{try{JSONArray out=new JSONArray();for(DocumentSnapshot x:s){JSONObject o=new JSONObject();o.put("id",x.getId());o.put("name",x.getString("customerName"));o.put("mobile",x.getString("mobile"));o.put("address",x.getString("address"));o.put("total",x.getLong("total")!=null?x.getLong("total"):0);o.put("status",String.valueOf(x.get("status")));out.put(o);}js("window.adminOrdersResult("+JSONObject.quote(out.toString())+");");}catch(Exception e){js("window.adminError('Could not load orders.');");}});});}
void status(String id,String st){if(a.getCurrentUser()==null)return;db.collection("admins").document(a.getCurrentUser().getUid()).get().addOnSuccessListener(d->{if(!d.exists()){js("window.adminError('Admin access denied.');");return;}if(!Arrays.asList("PLACED","ACCEPTED","PREPARING","OUT_FOR_DELIVERY","DELIVERED","CANCELLED").contains(st))return;db.collection("orders").document(id).update("status",st).addOnSuccessListener(x->adminOrders());});}
@Override public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==LOC){if(g.length>0&&(g[0]==PackageManager.PERMISSION_GRANTED||(g.length>1&&g[1]==PackageManager.PERMISSION_GRANTED)))locate();else js("window.orderError('Location permission is required to verify the 5 km delivery area.');");}}
public class Bridge{@JavascriptInterface public void sendOtp(String p){runOnUiThread(()->send(p));}@JavascriptInterface public void verifyOtp(String c){runOnUiThread(()->verify(c));}@JavascriptInterface public void placeOrder(String n,String p,String ad,String i,int s){runOnUiThread(()->order(n,p,ad,i,s));}@JavascriptInterface public void loadLastOrder(){runOnUiThread(()->loadLast());}@JavascriptInterface public void cancelLastOrder(){runOnUiThread(()->{String id=getPreferences(0).getString("lastOrderId",null);if(id!=null&&a.getCurrentUser()!=null)db.collection("orders").document(id).get().addOnSuccessListener(d->{if(a.getCurrentUser().getUid().equals(d.getString("userId")))db.collection("orders").document(id).update("status","CANCELLED");});});}@JavascriptInterface public void getLocation(){runOnUiThread(()->locate());}@JavascriptInterface public void getOrderHistory(){runOnUiThread(()->history());}@JavascriptInterface public void getProfile(){runOnUiThread(()->profile());}@JavascriptInterface public void saveProfile(String n,String p){runOnUiThread(()->saveProfile(n,p));}@JavascriptInterface public void getAddresses(){runOnUiThread(()->addresses());}@JavascriptInterface public void saveAddress(String l,String ad){runOnUiThread(()->saveAddress(l,ad));}@JavascriptInterface public void submitReview(String id,int r,String c){runOnUiThread(()->review(id,r,c));}@JavascriptInterface public void checkAdmin(){runOnUiThread(()->adminCheck());}@JavascriptInterface public void adminOrders(){runOnUiThread(()->adminOrders());}@JavascriptInterface public void updateOrderStatus(String id,String st){runOnUiThread(()->status(id,st));}}
}
